import{_ as e,o,c as r,ag as t}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Propriedade","description":"","frontmatter":{},"headers":[],"relativePath":"pt/repair-station-business/ownership.md","filePath":"pt/repair-station-business/ownership.md"}'),s={name:"pt/repair-station-business/ownership.md"};function i(n,a,d,p,m,c){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="propriedade" tabindex="-1">Propriedade <a class="header-anchor" href="#propriedade" aria-label="Permalink to &quot;Propriedade&quot;">​</a></h1><h2 id="colocar-uma-estacao-a-venda" tabindex="-1">Colocar uma estação à venda <a class="header-anchor" href="#colocar-uma-estacao-a-venda" aria-label="Permalink to &quot;Colocar uma estação à venda&quot;">​</a></h2><p>Só as estações à venda podem ser compradas. Como admin com <code>nay_repair_business.config</code>:</p><ol><li>Crie as estações com o <a href="/pt/repair-station/stations">editor da Repair Station</a>.</li><li>Abra o painel de administração com <code>/nay:repairbusiness</code>, ou pela ação <strong>Gerir estações à venda</strong> do <code>/nay</code>.</li><li>Escolha uma estação, escreva um preço de venda e prima <strong>Pôr à venda</strong>.</li></ol><p>A mesma lista existe no <code>/nay</code> como <strong>Estações à venda</strong>. Uma estação à venda mostra um blip no mapa e um aviso com o preço. Enquanto ninguém a possui, <strong>Estações à venda sem proprietário</strong> decide se fica aberta (os jogadores reparam lá como de costume) ou fecha até alguém a comprar. Uma estação desativada na Repair Station não pode ser comprada e não mostra blip.</p><h2 id="comprar" tabindex="-1">Comprar <a class="header-anchor" href="#comprar" aria-label="Permalink to &quot;Comprar&quot;">​</a></h2><p>O jogador vai à estação e prime <strong>E</strong>. Uma confirmação mostra o preço e a conta de onde é pago (<strong>Conta de compra</strong>). Um jogador pode possuir até <strong>Estações por jogador</strong> estações. O servidor verifica a compra, a 8 metros da estação no máximo, e reembolsa-a se algo falhar.</p><h2 id="o-tablet" tabindex="-1">O tablet <a class="header-anchor" href="#o-tablet" aria-label="Permalink to &quot;O tablet&quot;">​</a></h2><p>O proprietário prime <strong>E</strong> na estação para abrir o tablet, a 8 metros ou menos:</p><ul><li><strong>Resumo</strong>: stock, caixa, reparações do dia e dos últimos 7 dias, últimas operações.</li><li><strong>Stock</strong>: comprar peças ou entregar objetos, veja <a href="/pt/repair-station-business/stock">Stock</a>.</li><li><strong>Caixa</strong>: levantar dinheiro para numerário ou banco, ou depositar dinheiro do banco na caixa.</li><li><strong>Definições</strong>: percentagem dos preços, nome da estação, venda da estação.</li></ul><p>O nome escolhido pelo proprietário substitui o nome da estação no menu de reparação. A percentagem altera o preço de cada serviço: os jogadores veem o preço final antes de pagar, e o imposto (<strong>Imposto</strong>) é retido em cada pagamento, a caixa recebe o resto.</p><h2 id="vender-e-perder-uma-estacao" tabindex="-1">Vender e perder uma estação <a class="header-anchor" href="#vender-e-perder-uma-estacao" aria-label="Permalink to &quot;Vender e perder uma estação&quot;">​</a></h2><ul><li><strong>Venda</strong>: o proprietário recebe a percentagem <strong>Recompra</strong> do preço de compra, mais a caixa, no banco. A estação volta a estar à venda pelo seu preço, a menos que a equipa a tenha retirado da venda.</li><li><strong>Expulsão</strong>: a equipa pode expulsar um proprietário no painel de administração. É pago como numa venda.</li><li><strong>Inatividade</strong>: um proprietário que não abra o tablet durante <strong>Limite de inatividade</strong> dias perde a estação e é pago como numa venda. 0 desativa.</li><li><strong>Estação removida</strong>: quando uma estação é apagada no editor da Repair Station, o proprietário é pago como numa venda e a estação sai do sistema.</li></ul><p>Um proprietário offline nesse momento recebe o dinheiro, uma só vez, na próxima vez que a personagem for carregada, com uma notificação. Cada operação fica registada no registo, que se lê com a <a href="/pt/repair-station-business/api">API</a>.</p>',14)])])}const g=e(s,[["render",i]]);export{u as __pageData,g as default};
